import {brushes,settings,strokeMarkup,previewPoints} from './drawing.js';
export const palette=[['Ink','#292536'],['Slate','#68738a'],['White','#ffffff'],['Red','#e34a59'],['Orange','#ec8b35'],['Green','#259b73'],['Blue','#3278e4'],['Purple','#794de8']];
export function drawingControls(values,disabled=false){const s=settings(values),off=disabled?'disabled':'',smoothOff=s.perfectStroke||disabled?'disabled':'';return `<div class="draw-settings"><div class="draw-label">Brush</div><div class="brush-grid" role="group" aria-label="Brush">${brushes.map(brush=>`<button class="brush-option ${s.brush===brush.id?'chosen':''}" data-brush="${brush.id}" aria-pressed="${s.brush===brush.id}" ${off}><svg viewBox="0 0 216 64" aria-hidden="true">${strokeMarkup(previewPoints,{...s,brush:brush.id,stroke:brush.id==='pencil'?3:brush.id==='fineliner'?2.5:6})}</svg><span>${brush.name}</span><small>${brush.description}</small></button>`).join('')}</div><div class="draw-label">Color</div><div class="color-picker-row"><div class="color-wheel" data-color-wheel role="slider" tabindex="0" aria-label="Brush hue" style="--current:${s.color}"><span></span></div><label class="color-hex"><span>Exact color</span><input data-draw-prop="color" type="color" value="${s.color}" ${off}></label></div><div class="color-palette" role="group" aria-label="Drawing color">${palette.map(([name,color])=>`<button class="color-swatch ${s.color.toLowerCase()===color?'chosen':''}" data-draw-color="${color}" aria-label="${name}" aria-pressed="${s.color.toLowerCase()===color}" title="${name}" style="--swatch:${color}" ${off}></button>`).join('')}</div><div class="draw-range"><label for="draw-width">Width</label><output id="draw-width-value" for="draw-width">${s.stroke} px</output><input id="draw-width" data-draw-prop="stroke" type="range" min="1" max="30" step=".5" value="${s.stroke}" ${off}></div><div class="draw-range"><label for="draw-opacity">Opacity</label><output id="draw-opacity-value" for="draw-opacity">${s.opacity}%</output><input id="draw-opacity" data-draw-prop="opacity" type="range" min="1" max="100" step="1" value="${s.opacity}" ${off}></div>${s.brush==='pencil'?`<div class="draw-range pencil-texture"><label for="draw-pencil-texture">Graphite grain</label><output id="draw-pencil-texture-value" for="draw-pencil-texture">${s.pencilTexture}%</output><input id="draw-pencil-texture" data-draw-prop="pencilTexture" type="range" min="0" max="100" step="1" value="${s.pencilTexture}" ${off}><div class="range-extremes"><span>Clean</span><span>Sketchy</span></div></div>`:''}<div class="draw-label">Stroke correction</div><label class="perfect-stroke smooth-stroke"><input data-draw-prop="smoothStroke" type="checkbox" role="switch" ${s.smoothStroke?'checked':''} ${smoothOff}><span><b>Smooth stroke</b><small>Remove mouse wobble while keeping the gesture you intended.</small></span></label>${s.smoothStroke?`<div class="smooth-controls ${s.perfectStroke?'disabled-range':''}"><div class="draw-range"><label for="draw-smooth-quality">Quality</label><output id="draw-smooth-quality-value" for="draw-smooth-quality">${s.smoothQuality}</output><input id="draw-smooth-quality" data-draw-prop="smoothQuality" type="range" min="1" max="100" step="1" value="${s.smoothQuality}" ${smoothOff}><div class="range-extremes"><span>Fast</span><span>Refined</span></div></div><div class="draw-range"><label for="draw-smooth-weight">Weight</label><output id="draw-smooth-weight-value" for="draw-smooth-weight">${s.smoothWeight}</output><input id="draw-smooth-weight" data-draw-prop="smoothWeight" type="range" min="1" max="100" step="1" value="${s.smoothWeight}" ${smoothOff}><div class="range-extremes"><span>Responsive</span><span>Rigid</span></div></div></div>`:''}<label class="perfect-stroke"><input data-draw-prop="perfectStroke" type="checkbox" role="switch" ${s.perfectStroke?'checked':''} ${off}><span><b>Perfect stroke</b><small>Replace the gesture with a clean line, ellipse, or flowing curve.</small></span></label><label class="perfect-stroke dynamics-switch"><input data-draw-prop="pressureDynamics" type="checkbox" role="switch" ${s.pressureDynamics?'checked':''} ${off}><span><b>Pressure dynamics</b><small>Use stylus pressure—or mouse speed—for expressive brush width.</small></span></label><div class="stroke-preview"><svg id="draw-preview" viewBox="0 0 216 64" aria-label="Current brush stroke preview">${strokeMarkup(previewPoints,s)}</svg></div><p class="draw-description">Hold Shift and click to continue from the previous stroke with a straight segment.</p></div>`;}
